query:
query privateApplicationPrivateApplication ( $accountId:ID! $privateApplicationRefInput:PrivateApplicationRefInput!) {
	privateApplication ( accountId:$accountId ) {
		privateApplication ( input:$privateApplicationRefInput  )  {
			id
			creationTime
			name
			description
			internalAppAddress
			probingEnabled
			published
			allowIcmpProtocol
			publishedAppDomain {
				id
				creationTime
				publishedAppDomain
				catoIp
				connectorGroupName
			}
			privateAppProbing {
				id
				type
				interval
				faultThresholdDown
			}
			protocolPorts {
				port
				portRange {
					from
					to
				}
				protocol
			}
			connectivityStatus
		}
	}	
}
